SELECT platba."Èíslo ¾ádosti o platbu" ,
       platba.kodwfstav,
       rf.CASTKASCHVALENA "Èástka schválená" ,
       apfm.pocet "Poèet vrácení P5T -> P4" ,
       apfm.posldatum "Poslední vrácení P5T -> P4" ,
       apfm6.pocet "Poèet vrácení P6 -> P4" ,
       apfm6.posldatum  "Poslední vrácení P6 -> P4" ,
       MIN(CASE WHEN sk.nazev = 'Kontrolní list è.1346-NPO-Kontrolní list pro kontrolu ®oP - finanèní - 2. stupeò (MPIK 13.10.2023)' THEN 'ANO'
	     WHEN sk.nazev = 'Kontrolní list è.0144-OPPIK-Kontrolní list pro II. stupeò kontroly ®oP - úplnosti a finanèní' THEN '144'
	     ELSE 'NE'
	     END) "Obsahuje KL 1346"


FROM isum.v_bi_UmzProjekt p 
INNER JOIN isum.v_bi_UmpPlatbaPrj platba ON p.id=platba.id_NositelPlatby
INNER JOIN isum.v_bi_UmpRozpisFin rf ON rf.id_platba = platba.id AND rf.id_ukazatel in ( 361356 ) -- øádky cis.
LEFT JOIN (SELECT NositelId,
     	  	  count(id) pocet,
		  max(datumod) posldatum
     	   FROM isum.v_bi_UmsWFHistorieStavu
	   WHERE stavz IN ('P5T')
	   AND stavdo = 'P4'
	   GROUP BY Nositelid ) apfm ON  apfm.NositelId = platba.id 

LEFT JOIN (SELECT NositelId,
     	  	  count(id) pocet,
		  max(datumod) posldatum
     	   FROM isum.v_bi_UmsWFHistorieStavu
	   WHERE stavz IN ('P6')
	   AND stavdo = 'P4'
	   GROUP BY Nositelid ) apfm6 ON  apfm6.NositelId = platba.id 
INNER JOIN isum.V_BI_UMVKontrola k ON k.id_nositelkontroly = p.id
INNER JOIN isum.v_bi_UmvHodnoceni h ON k.id = h.id_kontrola 
-- INNER JOIN isum.v_bi_UmzProjekt p ON k.id_nositelkontroly = p.id 
LEFT JOIN isum.V_BI_UMVHodnSouborKrit sk ON sk.id = h.id_souborkrit AND (sk.nazev = 'Kontrolní list è.1346-NPO-Kontrolní list pro kontrolu ®oP - finanèní - 2. stupeò (MPIK 13.10.2023)' OR sk.nazev = 'Kontrolní list è.0144-OPPIK-Kontrolní list pro II. stupeò kontroly ®oP - úplnosti a finanèní' )


-- WHERE platba."Èíslo ¾ádosti o platbu" like 'CZ.01.1.02/0.0/0.0/15_002/0000006%'





