----------------------------------------
SELECT	p."Registraèní èíslo projektu",
	CASE WHEN sk.nazev = 'Kontrolní list è.1346-NPO-Kontrolní list pro kontrolu ®oP - finanèní - 2. stupeò (MPIK 13.10.2023)' THEN 'ANO'
	     WHEN sk.nazev = 'Kontrolní list è.0144-OPPIK-Kontrolní list pro II. stupeò kontroly ®oP - úplnosti a finanèní' THEN 'NE'
	     END "Obsahuje KL 1346"
FROM isum.v_bi_UmvHodnoceni h 
INNER JOIN isum.V_BI_UMVKontrola k ON k.id = h.id_kontrola
INNER JOIN isum.v_bi_UmzProjekt p ON k.id_nositelkontroly = p.id 
INNER JOIN isum.V_BI_UMVHodnSouborKrit sk ON sk.id = h.id_souborkrit

WHERE h.id IN (1833503150, 561746388)



----------------------------------------

SELECT p."Registraèní èíslo projektu" ,
       knm."KOD#Èíslo kontroly",
       hod.*

FROM isum.v_bi_UmzProjekt p
INNER JOIN isum.v_bi_UMVKontrolaNaMiste knm ON knm.id_nositelkontroly = p.id
INNER JOIN isum.v_bi_UmvHodnoceni hod ON hod.id_noshodnoceni = knm.id 

WHERE hod.id is not null
AND p."Registraèní èíslo projektu" like 'CZ.31.3%'


WHERE knm.id = 1833503125
